<script setup lang="ts">
const api=window.teachshelf;
import {computed,reactive} from 'vue';
import {dateMs,SWIFT_EPOCH_MS,swiftNow} from '../../shared/model';
import type {StudyTask} from '../../shared/model';
import Modal from './Modal.vue';
import {useLibrary} from '../stores/library';
const props=defineProps<{task?:StudyTask}>(),emit=defineEmits<{close:[]}>(),store=useLibrary();
function local(value?:number|string){const d=new Date(value===undefined?Date.now():dateMs(value));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
const form=reactive({title:props.task?.title??'',content:props.task?.content??'',kind:props.task?.kind??'任务',courseID:props.task?.courseID??store.courseID??'',materialIDs:[...(props.task?.materialIDs??[])],startsAt:local(props.task?.startsAt),endsAt:local(props.task?.endsAt??(props.task?dateMs(props.task.startsAt)/1000-SWIFT_EPOCH_MS/1000+3600:undefined)),hasEnd:props.task?.endsAt!==undefined,hasExecutionTime:props.task?.hasExecutionTime??true,hasDeadline:props.task?.deadline!==undefined,deadline:local(props.task?.deadline),isAllDay:props.task?.isAllDay??false,deadlineIsAllDay:props.task?.deadlineIsAllDay??false,showOnCalendar:props.task?.showOnCalendar??true,location:props.task?.location??'',completionRequired:props.task?.completionRequired??true});
const complex=computed(()=>!!props.task?.repeatRule||!!props.task?.exceptions?.length||props.task?.origin==='fixed');
const materials=computed(()=>store.state.materials.filter(m=>!form.courseID||m.courseID===form.courseID));
function seconds(value:string){const time=new Date(value).getTime();if(!Number.isFinite(time))throw new Error('请输入有效日期');return(time-SWIFT_EPOCH_MS)/1000;}
async function save(){let task:Partial<StudyTask>&{title:string};if(complex.value){task={id:props.task!.id,title:form.title};}else{task={...(props.task?{id:props.task.id}:{}),title:form.title,content:form.content,kind:form.kind,courseID:form.courseID||undefined,materialIDs:[...form.materialIDs],startsAt:seconds(form.startsAt),endsAt:form.hasEnd?seconds(form.endsAt):undefined,hasExecutionTime:form.hasExecutionTime,deadline:form.hasDeadline?seconds(form.deadline):undefined,isAllDay:form.isAllDay,deadlineIsAllDay:form.deadlineIsAllDay,showOnCalendar:form.showOnCalendar,location:form.location,completionRequired:form.completionRequired,origin:props.task?.origin??'activity',showInMonth:props.task?.showInMonth??true};}const result=await store.change(()=>api.saveTask(task),'计划已保存');if(result)emit('close');}
</script>
<template><Modal :title="task?'编辑计划':'新建计划'" @close="emit('close')"><form class="form-stack" @submit.prevent="save"><label>计划名称<input v-model="form.title" required maxlength="500"/></label><label>内容<textarea v-model="form.content" rows="3" :disabled="complex"/></label><p v-if="complex" class="warning-banner">此计划包含重复规则、单次例外或固定课程。当前仅支持修改名称，原规则会完整保留。</p><template v-else><div class="form-row"><label>类型<input v-model="form.kind" list="plan-kinds"/><datalist id="plan-kinds"><option>任务</option><option>作业</option><option>考试</option><option>活动</option></datalist></label><label>课程<select aria-label="课程" v-model="form.courseID"><option value="">不关联课程</option><option v-for="c in store.state.courses" :key="c.id" :value="c.id">{{c.name}}</option></select></label></div><div class="form-row"><label class="check-label"><input type="checkbox" v-model="form.hasExecutionTime"/>安排执行时间</label><label class="check-label"><input type="checkbox" v-model="form.isAllDay"/>全天</label></div><label v-if="form.hasExecutionTime">开始时间<input type="datetime-local" v-model="form.startsAt" required/></label><label v-if="form.hasExecutionTime" class="check-label"><input type="checkbox" v-model="form.hasEnd"/>设置结束时间</label><label v-if="form.hasExecutionTime&&form.hasEnd">结束时间<input type="datetime-local" v-model="form.endsAt" required/></label><label class="check-label"><input type="checkbox" v-model="form.hasDeadline"/>设置截止时间</label><div v-if="form.hasDeadline" class="form-row"><label>截止时间<input type="datetime-local" v-model="form.deadline" required/></label><label class="check-label"><input type="checkbox" v-model="form.deadlineIsAllDay"/>截止日全天</label></div><label>地点<input v-model="form.location"/></label><div class="form-row"><label class="check-label"><input type="checkbox" v-model="form.completionRequired"/>需要标记完成</label><label class="check-label"><input type="checkbox" v-model="form.showOnCalendar"/>显示在日历</label></div><label v-if="materials.length">关联资料<select v-model="form.materialIDs" multiple class="material-select"><option v-for="m in materials" :key="m.id" :value="m.id">{{m.title}}</option></select><small class="field-note">按住 Command / Ctrl 可选择多份资料。</small></label></template><div class="dialog-actions"><span class="spacer"/><button type="button" @click="emit('close')">取消</button><button class="primary" :disabled="!form.title.trim()||!!store.busy">保存</button></div></form></Modal></template>
